source.excerpt:
\begin{prop}\ollabel{prop:enum-bij}
If $f\colon \PosInt \to A$ is !!{surjective} (i.e., an enumeration
of~$A$), there is !!a{bijection} $g\colon Z \to A$ where $Z$ is
either~$\PosInt$ or $\{1, \dots, n\}$ for some~$n \in \PosInt$.
\end{prop}

target.excerpt:
\begin{prop}\ollabel{prop:enum-bij}
$f\colon \PosInt \to A$ हे !!{surjective} असेल (म्हणजे~$A$
चे प्रगणन असेल), तर !!a{bijection} $g\colon Z \to A$ असते,
जेथे $Z$ हा~$\PosInt$ किंवा कोणत्या तरी~$n \in \PosInt$
साठी $\{1, \dots, n\}$ असतो.
\end{prop}

  फलन $g$ हे !!{surjective} आहे, कारण~$A$ मधील कोणताही घटक
  $f(1)$, $f(2)$, \dots{} यांमध्ये येतो ($f$ हे !!{surjective}
  असल्यामुळे), आणि म्हणून कधी ना कधी तो कोणत्या तरी~$i$
  साठीचे~$g(i)$ चे मूल्य होईल. ते !!{injective} ही आहे:
  $g(j) = g(i)$ असणारे $j < i$ असते, तर $g(i)$ हे मूल्य
  आधीच $g(1)$, \dots, $g(i-1)$ यांमध्ये आलेले असते;
  पण हे~$g$ च्या आपल्या व्याख्येविरुद्ध आहे.
\end{proof}

source.excerpt:
\begin{cor}\ollabel{cor:enum-nat-bij}
A set $A$ is !!{enumerable} iff it is empty or there is !!a{bijection}
$f\colon N \to A$ where either $N = \Nat$ or $N = \{0, \dots, n\}$ for
some $n \in \Nat$.
\end{cor}

target.excerpt:
\begin{cor}\ollabel{cor:enum-nat-bij}
संच $A$ हा !!{enumerable} असतो तेव्हा आणि केवळ तेव्हाच, जेव्हा
तो रिक्त असतो किंवा !!a{bijection} $f\colon N \to A$ असते,
जेथे $N = \Nat$ किंवा कोणत्या तरी $n \in \Nat$ साठी
$N = \{0, \dots, n\}$ असते.
\end{cor}

source.excerpt:
\begin{proof}
$A$ is !!{enumerable} iff $A$ is empty or there is !!a{surjective}
$f\colon \PosInt \to A$. By \olref{prop:enum-bij}, the latter holds
iff there is !!a{bijective} function~$f\colon Z \to A$ where $Z =
\PosInt$ or $Z = \{1, \dots, n\}$ for some $n \in \PosInt$. By the
same argument as in the proof of \olref{prop:enum-shift}, that in turn
is the case iff there is !!a{bijection} $g\colon N \to A$ where either
$N = \Nat$ or $N = \{0, \dots, n-1\}$.
\end{proof}

\begin{prob}
