\begin{defn}
If $A$ is a set of sets, then $\bigcup A$ is the set of !!{element}s of
!!{element}s of~$A$:
\begin{align*}
\bigcup A & = \Setabs{x}{x \text{ belongs to !!a{element} of } A},
\text{ i.e.,}\\
& = \Setabs{x}{\text{there is a } B \in A
  \text{ so that } x \in B}
\end{align*}
\end{defn}

target.excerpt:
\begin{defn}
$A$ हा संचांचा संच असेल, तर $\bigcup A$ म्हणजे $A$ मधील
!!{element}s यांत असणाऱ्या !!{element}s यांचा संच:
\begin{align*}
\bigcup A & = \Setabs{x}{x \text{ ही पुढील संचाच्या एका !!a{element}ात असते: } A},
\text{ म्हणजे,}\\
& = \Setabs{x}{\text{असा } B \in A
  \text{ असतो की } x \in B}
\end{align*}
\end{defn}

source.excerpt:
\begin{defn}
If $A$ is a set of sets, then $\bigcap A$ is the set of objects which
all elements of~$A$ have in common:
\begin{align*}
\bigcap A & = \Setabs{x}{x \text{ belongs to every !!{element} of } A},
\text{ i.e.,}\\
 & = \Setabs{x}{\text{for all } B \in A, x \in B}
\end{align*}
\end{defn}

target.excerpt:
\begin{defn}
$A$ हा संचांचा संच असेल, तर $\bigcap A$ म्हणजे $A$ मधील सर्व घटकांत
सामाईक असणाऱ्या वस्तूंचा संच:
\begin{align*}
\bigcap A & = \Setabs{x}{x \text{ ही पुढील संचाच्या प्रत्येक !!{element}ात असते: } A},
\text{ म्हणजे,}\\
 & = \Setabs{x}{\text{प्रत्येक } B \in A, x \in B}
\end{align*}
\end{defn}

