source.excerpt:
\begin{defn}
A function $g \colon B \to A$ is an \emph{inverse} of a function $f
\colon A \to B$ if $f(g(y)) = y$ and $g(f(x)) = x$ for all $x \in A$
and $y \in B$.
\end{defn}

target.excerpt:
\begin{defn}
सर्व $x \in A$ आणि $y \in B$ साठी $f(g(y)) = y$ आणि $g(f(x)) = x$
असेल, तर $g \colon B \to A$ हे फलन $f \colon A \to B$ या फलनाचा
\emph{व्युत्क्रम} असते.
\end{defn}

source.excerpt:
\begin{prop}
If $f\colon A \to B$ is !!{injective}, then there is a \emph{left
inverse}~$g\colon B \to A$ of~$f$ so that $g(f(x)) = x$ for all $x
\in A$.
\end{prop}

target.excerpt:
